const fs=require("fs");
const src=fs.readFileSync("services/YtMusic.qml","utf8");

const logDef=src.match(/function\s+_log\s*\(([^)]*)\)\s*\{([^}]*)\}/);
if(!logDef) process.exit(90);
if(logDef[1].trim()!=="msg") process.exit(91);
if(!logDef[2].includes("console.log(msg)")) process.exit(92);

const call1='root._log("[YtMusic] Browser detection done. Detected:")';
const call2='root._log("[YtMusic] Deps ready + browsers already detected:")';
if(!src.includes(call1)) process.exit(93);
if(!src.includes(call2)) process.exit(94);

const forbidden=[
  'root._log("[YtMusic] Browser detection done. Detected:", JSON.stringify(root.detectedBrowsers)',
  'root._log("[YtMusic] Deps ready + browsers already detected:", JSON.stringify(root.detectedBrowsers)'
];
for(const token of forbidden) if(src.includes(token)) process.exit(95);

// Semantic guard: a one-parameter logger that only consumes/prints its first
// argument cannot observe removed extra arguments, while JavaScript would have
// evaluated those arguments before the call.
function oldCall(verbose, trace, first) {
  function log(msg){ if(verbose) trace.push("print:"+msg); }
  function expensive(){ trace.push("json"); return JSON.stringify(["firefox","chromium"]); }
  log(first, expensive(), "ignored");
}
function newCall(verbose, trace, first) {
  function log(msg){ if(verbose) trace.push("print:"+msg); }
  log(first);
}
for(const verbose of [false,true]) {
  for(const first of [
    "[YtMusic] Browser detection done. Detected:",
    "[YtMusic] Deps ready + browsers already detected:"
  ]) {
    const a=[],b=[];
    oldCall(verbose,a,first);
    newCall(verbose,b,first);
    const oldObservable=a.filter(x=>x.startsWith("print:"));
    const newObservable=b.filter(x=>x.startsWith("print:"));
    if(JSON.stringify(oldObservable)!==JSON.stringify(newObservable)) process.exit(10);
    if(a.filter(x=>x==="json").length!==1) process.exit(11);
    if(b.filter(x=>x==="json").length!==0) process.exit(12);
  }
}
process.exit(0);
